class ApronFemaleFace extends StatelessWidget {
  final ApronFemaleFaceType type;
  final ApronFemaleFaceExpression expression;
  final double? width;
  final double? height;
  final ColorMapper? colorMapper;

  const ApronFemaleFace({
    required this.type,
    required this.expression,
    this.width,
    this.height,
    this.colorMapper,
    super.key,
  });

  @override
  Widget build(BuildContext context) {
    late String svgString;
    switch (expression) {
      case ApronFemaleFaceExpression.default_:
        switch (type) {
          case ApronFemaleFaceType.a:
            svgString = _femaleFaceTypeADefault;
          case ApronFemaleFaceType.b:
            svgString = _femaleFaceTypeBDefault;
          case ApronFemaleFaceType.c:
            svgString = _femaleFaceTypeCDefault;
