            svgString = _femaleFaceTypeBSad;
          case ApronFemaleFaceType.c:
            svgString = _femaleFaceTypeCSad;
        }
      case ApronFemaleFaceExpression.smile:
        switch (type) {
          case ApronFemaleFaceType.a:
            svgString = _femaleFaceTypeASmile;
          case ApronFemaleFaceType.b:
            svgString = _femaleFaceTypeBSmile;
          case ApronFemaleFaceType.c:
            svgString = _femaleFaceTypeCSmile;
        }
      case ApronFemaleFaceExpression.surprised:
        switch (type) {
          case ApronFemaleFaceType.a:
            svgString = _femaleFaceTypeASurprised;
          case ApronFemaleFaceType.b:
            svgString = _femaleFaceTypeBSurprised;
          case ApronFemaleFaceType.c:
            svgString = _femaleFaceTypeCSurprised;
        }
      case ApronFemaleFaceExpression.talk:
        switch (type) {
          case ApronFemaleFaceType.a:
            svgString = _femaleFaceTypeATalk;
          case ApronFemaleFaceType.b:
            svgString = _femaleFaceTypeBTalk;
          case ApronFemaleFaceType.c:
            svgString = _femaleFaceTypeCTalk;
        }
      case ApronFemaleFaceExpression.tilt:
        switch (type) {
          case ApronFemaleFaceType.a:
