            svgString = _femaleFaceTypeBWorry;
          case ApronFemaleFaceType.c:
            svgString = _femaleFaceTypeCWorry;
        }
    }
    return SvgPicture.string(
      svgString,
      height: height,
      width: width,
      colorMapper: colorMapper,
